/** A joke every minute */
const minuteJoke = async (): Promise<void> => {
  const jokes = [
    "Why don't scientists trust atoms? Because they make up everything.",
    "Why did the scarecrow win an award? He was outstanding in his field.",
    "What do you call fake spaghetti? An impasta.",
    "Why did the bicycle fall over? It was two-tired.",
    "Why can't a nose be twelve inches long? Because then it would be a foot.",
    "What do you call a bear with no teeth? A gummy bear.",
    "Why did the math book look sad? It had too many problems.",
    "What do you call cheese that isn't yours? Nacho cheese.",
    "I only know 25 letters of the alphabet. I don't know y.",
    "Why did the computer get cold? It left its Windows open.",
    "What do you call a sleeping dinosaur? A dino-snore.",
    "Why don't eggs tell jokes? They'd crack each other up."
  ];
  const index = Math.floor(Date.now() / 60000) % jokes.length;
  /** Send this minute's joke to your Inbox */
  await inbox.sendItem({ title: "Your minute of humor", body: jokes[index] });
};
const jokeWorkflow = await workflows.create({ name: "A joke every minute", definition: minuteJoke, triggers: [{ name: "Every minute", source: { kind: "cron.Schedule", expr: "* * * * *", tz: "UTC" } }] });
console.log(jokeWorkflow);
